CREATE POLICY "Allow authenticated deletes in own folder" ON storage.objects AS PERMISSIVE FOR DELETE TO "authenticated" USING (((bucket_id = 'memories'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Allow authenticated reads in own folder" ON storage.objects AS PERMISSIVE FOR SELECT TO "authenticated" USING (((bucket_id = 'memories'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Allow authenticated updates in own folder" ON storage.objects AS PERMISSIVE FOR UPDATE TO "authenticated" USING (((bucket_id = 'memories'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]))) WITH CHECK (((bucket_id = 'memories'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Allow authenticated uploads in own folder" ON storage.objects AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((bucket_id = 'memories'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "multilingual_storage_delete_guard" ON storage.objects AS RESTRICTIVE FOR DELETE TO "anon", "authenticated" USING (public.legacy_storage_mutation_allowed_v1(bucket_id, name));
CREATE POLICY "multilingual_storage_insert_guard" ON storage.objects AS RESTRICTIVE FOR INSERT TO "anon", "authenticated" WITH CHECK (public.legacy_storage_mutation_allowed_v1(bucket_id, name));
CREATE POLICY "multilingual_storage_update_guard" ON storage.objects AS RESTRICTIVE FOR UPDATE TO "anon", "authenticated" USING (public.legacy_storage_mutation_allowed_v1(bucket_id, name)) WITH CHECK (public.legacy_storage_mutation_allowed_v1(bucket_id, name));
